    adult: [
      { id:"e_l2a_1", section:"vocabulary", q:"ما مَعْنَى كَلِمَةِ (مَوْعِد)؟", opts:["وَقْتٌ مُتَّفَقٌ عَلَيْهِ لِلِّقَاء","مَكَانٌ يُزَاوِلُ فِيهِ النَّاسُ عَمَلَهُم","نَوْعٌ مِنَ الطَّعَامِ يُقَدَّمُ لِلضُّيُوف","وَسِيلَةُ نَقْلٍ تَسِيرُ فِي المَدِينَة"], answer:0, rtl:true, explain:"الموعد: الوقت المتّفق عليه." },
      { id:"e_l2a_2", section:"vocabulary", q:"ما مُرَادِفُ كَلِمَةِ (ضَرُورِيّ)؟", opts:["اخْتِيَارِيٌّ يُمْكِنُ تَرْكُه","سَهْلٌ لَا جُهْدَ فِيه","لَازِمٌ لَا بُدَّ مِنْه","بَعِيدٌ يَصْعُبُ بُلُوغُه"], answer:2, rtl:true, explain:"الضروريّ: ما لا غنى عنه." },
      { id:"e_l2a_3", section:"grammar", q:"أَكْمِلْ: (كُنْتُ _____ فِي المَكْتَبِ عِنْدَمَا اتَّصَلْت).", opts:["أَعْمَلُ","عَمِلْتُ","سَأَعْمَلُ","اعْمَلْ"], answer:0, rtl:true, explain:"(كان + مضارع) يدلّ على عمل مستمرّ في الماضي." },
      { id:"e_l2a_4", section:"grammar", q:"أَكْمِلْ: (هَذِهِ سَيَّارَةُ _____ ).", opts:["الجَارُ","الجَارَ","الجَارِ","جَارٌ"], answer:2, rtl:true, explain:"المضاف إليه مجرور: سيّارةُ الجارِ." },
      { id:"e_l2a_5", section:"grammar", q:"ما جَمْعُ كَلِمَةِ (طَبِيب)؟", opts:["طَبِيبَان","أَطِبَّاء","تَطْبِيب","طِبّ"], answer:1, rtl:true, explain:"جمع طبيب: أطبّاء." },
      { id:"e_l2a_6", section:"reading", q:"(يَفْتَحُ البَنْكُ مِنَ التَّاسِعَةِ صَبَاحًا حَتَّى الثَّالِثَةِ عَصْرًا، وَيُغْلَقُ يَوْمَ الجُمُعَة). مَتَى يُغْلَقُ البَنْك؟", opts:["يَوْمَ الأَحَد","السَّاعَةَ التَّاسِعَة","كُلَّ مَسَاء","يَوْمَ الجُمُعَة"], answer:3, rtl:true, explain:"النصّ يذكر أنه يُغلق يوم الجمعة." },
      { id:"e_l2a_7", section:"reading", q:"(نَصَحَ الطَّبِيبُ المَرِيضَ بِالرَّاحَةِ وَشُرْبِ المَاءِ كَثِيرًا). بِمَاذَا نَصَح؟", opts:["بِالرَّاحَةِ وَشُرْبِ المَاء","بِالسَّفَرِ وَالعَمَل","بِالرِّيَاضَةِ الشَّدِيدَة","بِتَغْيِيرِ الوَظِيفَة"], answer:0, rtl:true, explain:"النصّ يذكر النصيحتين معاً." },
      { id:"e_l2a_8", section:"quran", q:"ما مَعْنَى (تَوَاصَوْا بِالصَّبْر)؟", opts:["صَبَرُوا وَحْدَهُم","أَوْصَى بَعْضُهُمْ بَعْضًا بِالصَّبْر","تَرَكُوا الصَّبْر","طَلَبُوا الصَّبْرَ مِنَ الله"], answer:1, rtl:true, explain:"التواصي فعل متبادل بين الجماعة." },
      { id:"e_l2a_9", section:"quran", q:"ما مَعْنَى (المِسْكِين) فِي القُرْآن؟", opts:["الغَنِيُّ البَخِيل","المُسَافِرُ الغَرِيب","الفَقِيرُ المُحْتَاج","العَامِلُ المُجْتَهِد"], answer:2, rtl:true, explain:"المسكين: من لا يجد كفايته من المال." },
      { id:"e_l2a_10", section:"quran", q:"ما مَعْنَى (اليَتِيم) فِي القُرْآن؟", opts:["مَنْ مَاتَ أَبُوهُ وَهُوَ صَغِير","مَنْ لَا مَالَ لَهُ وَلَا كَسْب","مَنْ يَعِيشُ وَحْدَهُ بِلَا أَهْل","مَنْ تَرَكَ بَلَدَهُ إِلَى بَلَدٍ آخَر"], answer:0, rtl:true, explain:"اليتيم في الإنسان: من فقد أباه قبل البلوغ." },
    ],
