// ─── Score Calculator ─────────────────────────────────────────────────────────
export function calcScore(answers) {
  return answers.filter(a => a.passed).length;
}

// ─── Google Sheets Integration ────────────────────────────────────────────────
// To activate: paste the Apps Script Web App URL below.
// The backend lives in apps-script/Code.gs and serves both RAQP and RQAP.
const SHEETS_URL = ''; // 👈 paste your Google Apps Script Web App URL here

export async function saveToSheets(resultData) {
  if (!SHEETS_URL) return { ok: false, reason: 'No Sheets URL configured' };
  try {
    await fetch(SHEETS_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(resultData),
      mode: 'no-cors',
    });
    return { ok: true };
  } catch (err) {
    console.warn('Sheets save failed:', err.message);
    return { ok: false, reason: err.message };
  }
}
